        int[] prices = {7, 6, 5, 4, 3, 2};
        int[] expectedSpans = {1, 1, 2, 2, 3};
        onlineStockSpan.list = new ArrayList<>(List.of(7, 6, 5, 4, 3, 2));
        int result[] = onlineStockSpan.calculateSpans(prices);
        assertEquals(expectedSpans, result);

        prices = new int[]{10, 22, 9, 33, 21, 50, 41, 60, 80};
        result = onlineStockSpan.calculateSpans(prices);
        assertEquals(new int[]{1, 2, 3, 4, 5, 6, 7, 8, 9}, result);
    }

}
